import{_ as s,I as a,c as o,o as l,a5 as r,J as t,w as d,aN as c,aO as h,aP as p,aQ as m,aR as u}from"./chunks/framework.Dl43PoGR.js";const C=JSON.parse('{"title":"Understanding Candles - Open, High, Low, Close","description":"","frontmatter":{"title":"Understanding Candles - Open, High, Low, Close","author":{"name":"Yogesh Patil"},"date":"2025-08-10T00:00:00.000Z","category":"trading-concepts","sidebar":true,"outline":"deep","prev":{"text":"Trading Posts Categories Form Now","link":"/post/other/trading-posts-categories-form-now"},"next":{"text":"Trading Psychology – Doubt","link":"/post/trader/trading-psychology-doubt"},"head":[["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"Understanding Candles - Open, High, Low, Close"}],["meta",{"property":"og:description","content":"Every candle tells a story. This guide breaks down OHLC, explains bullish vs. bearish structure, and shows how to spot directional, reversal, and indecision candles for cleaner entries."}],["meta",{"property":"og:image","content":"https://ystc.in/posts/ohlc-olhc.png"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:image","content":"https://ystc.in/posts/ohlc-olhc.png"}]]},"headers":[],"relativePath":"post/trading-concepts/understanding-candles-open-high-low-close.md","filePath":"post/trading-concepts/understanding-candles-open-high-low-close.md"}'),g={name:"post/trading-concepts/understanding-candles-open-high-low-close.md"};function f(b,e,w,y,v,k){const n=a("GraphComment"),i=a("ClientOnly");return l(),o("div",null,[e[0]||(e[0]=r('<h1 id="understanding-candles-open-high-low-close" tabindex="-1">Understanding Candles: Open, High, Low, Close <a class="header-anchor" href="#understanding-candles-open-high-low-close" aria-label="Permalink to “Understanding Candles: Open, High, Low, Close”">​</a></h1><p><em>August 10, 2025</em></p><p>Every candle tells a story. This guide breaks down OHLC, explains bullish vs. bearish structure, and shows how to spot directional, reversal, and indecision candles for cleaner entries.</p><p><img src="'+c+'" alt="ohlc-olhc.png"></p><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to “Introduction”">​</a></h2><p>In this post, we’re breaking down one of the most fundamental parts of trading: the open, high, low, and close of candles (OHLC). Every candle on every timeframe tells a story. By understanding what it’s showing you, you can better anticipate direction, identify reversals, and recognize consolidation in the market.</p><h2 id="defining-bullish-and-bearish-candles" tabindex="-1">Defining bullish and bearish candles <a class="header-anchor" href="#defining-bullish-and-bearish-candles" aria-label="Permalink to “Defining bullish and bearish candles”">​</a></h2><p>Every candle has four points:</p><ul><li>Open – where price starts for that time period</li><li>High – the highest price reached</li><li>Low – the lowest price reached</li><li>Close – where price ends for that time period</li></ul><p>If the close is below the open, that’s a bearish candle.</p><p>If the close is above the open, that’s a bullish candle.</p><p>This structure is the foundation of trading. From here, you can see how higher-timeframe candles are built from lower-timeframe movement and start grouping candles into the three main types.</p><p><img src="'+h+'" alt="Anatomy of candlestick.webp"></p><h2 id="directional-candles" tabindex="-1">Directional candles <a class="header-anchor" href="#directional-candles" aria-label="Permalink to “Directional candles”">​</a></h2><p>A directional candle moves mostly one direction throughout the time period.</p><ul><li>Bullish directional: price opens, dips a bit to form the low, trends upward most of the period, and closes near the high.</li><li>Bearish directional: price opens, pushes above the open to form the upper wick, trends down most of the period, and closes near the low.</li></ul><p>The tell: the wick is relatively small compared to the body, signaling a strong, one-sided move. On lower timeframes, you’ll usually see steady continuation in the same direction.</p><div class="tip custom-block github-alert"><p class="custom-block-title">Tip: 💡</p><p>Focus on expansion candles that have a small wick. Small wicks are the key to understanding which candles support expansion.</p></div><p><img src="'+p+'" alt="directional-candle-ohlc1.png"></p><h2 id="reversal-candles" tabindex="-1">Reversal candles <a class="header-anchor" href="#reversal-candles" aria-label="Permalink to “Reversal candles”">​</a></h2><p>Reversal candles show a shift in control within the same period. The wicks are typically larger than the body.</p><ul><li>Bearish reversal: price opens, pushes higher as if continuing up, then flips and closes lower.</li><li>Bullish reversal: price opens, dips lower as if continuing down, then flips and closes higher.</li></ul><p>On lower timeframes, it looks like a trend attempt that fails and snaps back. Seeing these at key levels can be an early cue that a larger turn is forming.</p><div class="tip custom-block github-alert"><p class="custom-block-title">Tip: 💡</p><p>If trading a reversal candle, focus on targeting: Opening price, current candles high or low.</p></div><p><img src="'+m+'" alt="reversal-candle-ohlc1.png"></p><h2 id="indecision-candles" tabindex="-1">Indecision candles <a class="header-anchor" href="#indecision-candles" aria-label="Permalink to “Indecision candles”">​</a></h2><p>Indecision candles form when the market can’t pick a direction.</p><ul><li>Price opens, makes a high and a low, but closes near the open.</li><li>Long wicks on both sides with a relatively small body.</li></ul><p>They often show up after big expansions or during low-volatility sessions. Think of them as a pause before the next push.</p><div class="tip custom-block github-alert"><p class="custom-block-title">Tip: 💡</p><p>Although often avoided, indecision candles can be traded by trading a deviation from a range back to the opening price.</p></div><p><img src="'+u+'" alt="indecision-candle-ohlc1.png"></p><h2 id="why-this-matters" tabindex="-1">Why this matters <a class="header-anchor" href="#why-this-matters" aria-label="Permalink to “Why this matters”">​</a></h2><p>Recognizing these three types helps you frame trades:</p><ul><li>Directional candles favor continuation setups.</li><li>Reversal candles warn of shifts in trend at relevant levels.</li><li>Indecision candles suggest consolidation and should be avoided.</li></ul><p>And remember: every higher-timeframe candle is built from smaller candles. Once you internalize OHLC, you can “see” the lower-timeframe path inside any bar.</p><h2 id="putting-it-into-practice" tabindex="-1">Putting it into practice <a class="header-anchor" href="#putting-it-into-practice" aria-label="Permalink to “Putting it into practice”">​</a></h2><p>When you study a chart, ask yourself what the previous candle did:</p><ul><li>Did this bar mostly move one way (directional)?</li><li>Did it try one way and then flip (reversal)?</li><li>Or did it lack direction (indecision)?</li></ul><p>When you learn to identify the previous candle type, you can layer those reads with your bias and anticipate the next. Blend with the phases of price for extra confluence. Understanding OHLC is how candles stop feeling random and how you learn to anticipate the market.</p><h2 id="comments" tabindex="-1">Comments <a class="header-anchor" href="#comments" aria-label="Permalink to “Comments”">​</a></h2>',40)),t(i,null,{default:d(()=>[t(n)]),_:1})])}const x=s(g,[["render",f]]);export{C as __pageData,x as default};
